WITH latest_match AS (SELECT s.*, x.job_title, x.employee_hire_date FROM departments s LEFT JOIN LATERAL (SELECT c.job_title, c.hire_date AS employee_hire_date FROM employees c WHERE c.dept_id = s.id ORDER BY c.salary DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT dept_name, COUNT(*) FILTER (WHERE dept_name = 'Legal') AS legal_rows, SUM(CASE WHEN job_title = 'Designer' THEN budget ELSE 0 END) AS designer_budget, SUM(CASE WHEN job_title = 'Manager' THEN budget ELSE 0 END) AS manager_budget FROM latest_match GROUP BY dept_name ORDER BY designer_budget
